+export async function listTasksPaginated(limit = 20, offset = 0, status?: string): Promise<PaginatedTasksResponse | null> {
+  const qs = new URLSearchParams()
+  qs.set('limit', String(limit))
+  qs.set('offset', String(offset))
+  if (status) qs.set('status', status)
+  const res = await fetch(`${BASE}/api/tasks?${qs.toString()}`, { credentials: CREDENTIALS, headers: AUTH_HEADERS })
+  if (!res.ok) return null
+  return res.json() as Promise<PaginatedTasksResponse>
+}
